#!/usr/bin/env python3
"""Sinh renderer/ai-work-gemini.js (window.AI_WORK_GEMINI, Bài 4–12 lớp Gemini, khóa AI cho người đi làm).
Nội dung dựa trên giáo trình "AI cho người đi làm (Văn phòng – Kế toán – Hành chính)" do anh Trường cung cấp,
trình bày theo thẻ, bổ sung ví dụ và bài thực hành có dữ liệu giả lập. Chạy: python3 tools/build-gemini-lessons.py"""
import json, html, pathlib
ROOT = pathlib.Path(__file__).resolve().parent.parent
e = html.escape

class L:
    def __init__(s, title, sub, tsum): s.title, s.sub, s.n, s.parts = title, sub, 0, []; s.parts.append(
        '<div class="tsum"><div class="tsum-l">Tóm tắt bài</div><ul>%s</ul></div>' % ''.join('<li><b>%s:</b> %s</li>' % kv for kv in tsum))
    def chap(s, t): s.parts.append('<h3 class="tchap">%s</h3>' % t)
    def card(s, t, body, cls=''):
        s.n += 1; s.parts.append('<section class="tcard%s"><h4><span class="tn">%d</span>%s</h4>%s</section>' % (cls, s.n, t, body))
    def out(s): return {'title': s.title, 'sub': s.sub, 'html': ''.join(s.parts)}

def ul(items): return '<ul class="tl">' + ''.join('<li>%s</li>' % i for i in items) + '</ul>'
def steps(items): return '<ol class="steps">' + ''.join('<li>%s</li>' % i for i in items) + '</ol>'
def table(head, rows): return '<div class="tbl-wrap"><table><thead><tr>%s</tr></thead><tbody>%s</tbody></table></div>' % (''.join('<th>%s</th>' % h for h in head), ''.join('<tr>%s</tr>' % ''.join('<td>%s</td>' % c for c in r) for r in rows))
def prompt(title, text): return '<div class="ptitle">%s</div><pre class="prompt">%s</pre>' % (title, e(text))
def data(label, text): return '<div class="ptitle">%s</div><pre class="pdata">%s</pre>' % (label, e(text))
def ex(title, bad, good, note=''):
    return ('<div class="ex"><div class="ex-t">%s</div><div class="ex-row"><div class="ex-bad"><b>Cách yếu</b><pre>%s</pre></div><div class="ex-good"><b>Cách chuẩn</b><pre>%s</pre></div></div>%s</div>'
            % (title, e(bad), e(good), '<p class="ex-note">%s</p>' % note if note else ''))
def tip(t): return '<div class="ttry" style="border-left-color:#1f6fb2;background:#eaf3ff"><span class="ttry-l" style="color:#1f6fb2">Gợi ý với Gemini</span><p>%s</p></div>' % t
def ans(body, label='Đáp án để tự đối chiếu (làm xong rồi hãy mở)'): return '<details class="tans"><summary>%s</summary>%s</details>' % (label, body)
NOTE = '<p class="tnote">Toàn bộ dữ liệu trong thẻ này là giả lập, dùng được an toàn với AI.</p>'
def prac(t, intro, blocks, steps_, answer): 
    return ('<p>%s</p>%s<ol class="tl">%s</ol>%s%s' % (intro, ''.join(blocks), ''.join('<li>%s</li>' % x for x in steps_), answer, NOTE))
WARN = '<div class="card warn"><div class="lbl">Lưu ý</div><p>Mọi tên, số liệu và tình huống trong bài là giả lập. Tính năng và giao diện của Gemini thay đổi theo gói tài khoản và thời điểm, hãy kiểm tra lại trong tài khoản của mình. Không đưa dữ liệu nội bộ vào AI nếu tổ chức chưa cho phép.</p></div>'

B = {}
# ---------------- Bài 4 ----------------
b = L('Bài 4 · Gemini và bản đồ công cụ cho khối văn phòng', 'AI làm tốt gì, không tự đảm bảo gì, chọn Gemini khi nào và quy trình 4 bước làm việc cùng AI.',
      [('Học xong bài này', 'Phân loại được đầu việc nên giao, giao có kiểm tra hay không nên giao cho AI; chọn đúng công cụ; áp dụng quy trình 4 bước'), ('Chuẩn bị', 'Tài khoản Gemini (hoặc công cụ AI đã được phép dùng); 8 đầu việc ở phần thực hành'), ('Sản phẩm', 'Bảng phân loại 8 đầu việc kèm lý do')])
b.parts.append(WARN)
b.chap('Chương 1. Nền tảng AI và bản đồ công cụ')
b.card('AI tạo sinh làm được gì, không làm được gì?', '<p>Gemini, ChatGPT, Claude hiểu ngôn ngữ tự nhiên, nhận ra quy luật và tổng hợp thông tin từ văn bản, hình ảnh, bảng tính hoặc tệp tài liệu. Người đi làm cần biết rõ ranh giới để giao việc đúng.</p>'
       + '<div class="cols"><div class="card ok"><div class="lbl">AI làm rất tốt</div>' + ul(['Tóm tắt tài liệu dài, chuỗi email', 'Soạn nháp email và văn bản hành chính', 'Dịch theo ngữ cảnh', 'Viết công thức bảng tính', 'Phân loại dữ liệu văn bản, trích thông tin từ ảnh hoặc bảng', 'Lập checklist, gợi ý cấu trúc báo cáo']) + '</div>'
       '<div class="card no" style="background:#fbe9e7"><div class="lbl">AI không tự đảm bảo chính xác</div>' + ul(['Tính toán phức tạp bằng lời văn mà không qua công thức', 'Trích số hiệu văn bản pháp luật mới nhất khi chưa kiểm tra nguồn', 'Quyết định nghiệp vụ có trách nhiệm pháp lý', 'Hiểu văn hóa nội bộ khi chưa được cung cấp']) + '</div></div>')
b.card('Chọn đúng công cụ cho đúng đầu việc', '<p>Đừng chỉ dùng một công cụ cho mọi việc. Biết thế mạnh từng nền tảng để kết hợp linh hoạt:</p>' + table(['Công cụ', 'Thế mạnh nổi bật', 'Tình huống ưu tiên'], [
    ['<b>Gemini (Google)</b>', 'Tích hợp với Gmail, Docs, Sheets, Drive, Meet; đọc được bộ tài liệu rất dài; xử lý tốt tệp âm thanh, video, bảng tính', 'Tóm tắt chuỗi email, làm việc trên Google Workspace, đọc cùng lúc nhiều báo cáo hoặc biên bản dài'],
    ['ChatGPT (OpenAI)', 'Đa năng, phản hồi nhanh, phân tích Excel/CSV linh hoạt, dễ tạo trợ lý tùy chỉnh', 'Phân tích bảng nhanh, lập kế hoạch sự kiện nội bộ, soạn nhiều mẫu truyền thông và biểu mẫu'],
    ['Claude (Anthropic)', 'Văn phong tiếng Việt tự nhiên, bám sát yêu cầu, ít suy diễn khi đọc hợp đồng hoặc quy định dài', 'Văn bản hành chính chuẩn mực, rà soát điều khoản, viết SOP và giải trình']])
       + tip('Cơ quan dùng Google Workspace thì Gemini thuận tiện nhất vì làm ngay trong Gmail, Docs, Sheets. Tính năng này tùy gói tài khoản; nếu chưa có, Anh/Chị vẫn dán nội dung vào khung chat Gemini.'))
b.card('Quy trình 4 bước làm việc cùng AI', steps(['<b>Chuẩn bị đầu vào sạch:</b> ẩn danh thông tin bảo mật, sắp dữ liệu nguồn rõ ràng (bảng, gạch đầu dòng, văn bản mẫu).', '<b>Giao việc có cấu trúc:</b> nêu vai trò, bối cảnh, nhiệm vụ, định dạng thay vì một câu hỏi rời rạc.', '<b>Kiểm tra chéo và tinh chỉnh:</b> đối chiếu con số, tên riêng, ngày tháng, điều khoản; yêu cầu sửa cụ thể từng chỗ chưa đạt.', '<b>Lưu thành mẫu dùng chung:</b> việc lặp hằng tuần, hằng tháng thì lưu câu lệnh chuẩn cho cả phòng.']))
b.card('Ví dụ: cùng một việc, hai cách giao', ex('Tóm tắt chuỗi email', 'Tóm tắt giúp tôi.', 'Hãy đọc chuỗi email dưới đây (đã ẩn danh) và tóm tắt thành 3 mục: (1) vấn đề cốt lõi, (2) nội dung đã thống nhất kèm tên người xác nhận, (3) việc tôi cần làm tiếp và thời hạn. Nếu mục nào không có trong email, ghi “không có”.', 'Cách chuẩn cho biết rõ kết quả cần có và cấm AI tự điền vào chỗ trống.'))
b.card('Thực hành: phân loại 8 đầu việc', prac('', 'Với mỗi việc, ghi một trong ba mức: <b>Giao AI</b> / <b>Giao nhưng phải kiểm tra</b> / <b>Không giao</b>, kèm lý do một câu. Làm trước, sau đó nhờ Gemini phản biện bảng của Anh/Chị.', [data('DỮ LIỆU MẪU – 8 đầu việc', '1. Tóm tắt chuỗi 12 email về lịch giao hàng\n2. Viết công thức SUMIFS cho bảng chi phí\n3. Quyết định có ký hợp đồng với nhà cung cấp B hay không\n4. Nêu số hiệu thông tư mới nhất về hóa đơn điện tử\n5. Soạn nháp thông báo nghỉ lễ\n6. Tải lên bảng lương chi tiết để xếp loại nhân viên\n7. Lập checklist tổ chức tiệc cuối năm\n8. “Cộng nhẩm” 300 dòng số tiền ngay trong khung chat'), prompt('PROMPT GỢI Ý', 'Dưới đây là bảng phân loại 8 đầu việc của tôi (Giao AI / Giao nhưng phải kiểm tra / Không giao). Hãy phản biện: chỗ nào tôi phân loại quá dễ dãi hoặc quá thận trọng, kèm lý do. Không đưa ra quyết định thay tôi.\n\n[dán bảng của bạn]')],
   ['Tự phân loại trên giấy, ghi lý do.', 'Dán bảng vào Gemini bằng prompt gợi ý và đọc phản biện.', 'So với đáp án, ghi lại chỗ Anh/Chị đã đổi ý.'],
   ans(ul(['<b>Giao AI:</b> 1 (nhưng kiểm tra ngày), 5, 7.', '<b>Giao nhưng phải kiểm tra:</b> 2 (thử kết quả bằng vài dòng tính tay), 4 (phải đối chiếu văn bản gốc, AI có thể nhớ sai số hiệu).', '<b>Không giao:</b> 3 (quyết định có trách nhiệm pháp lý, AI chỉ giúp so sánh), 6 (dữ liệu nhạy cảm, không đưa lên AI), 8 (không tính bằng lời, dùng công thức).'])))
           , ' tprac')
B['bai4'] = b.out()

# ---------------- Bài 5 ----------------
b = L('Bài 5 · Viết câu lệnh chuẩn bằng công thức R-C-T-F', 'Bốn thành phần của một câu lệnh dùng được ngay, ba kỹ thuật giảm sai sót và cách luyện từ câu lệnh yếu sang câu lệnh chuẩn.',
      [('Học xong bài này', 'Viết được câu lệnh đủ vai trò, bối cảnh, nhiệm vụ, định dạng; dùng mẫu, chia nhỏ việc và cho AI hỏi lại'), ('Chuẩn bị', 'Ba tình huống ở phần thực hành; Gemini'), ('Sản phẩm', '3 câu lệnh R-C-T-F dùng lại được')])
b.chap('Chương 2. Kỹ thuật viết câu lệnh (Prompt) chuẩn xác')
b.card('Công thức 4 thành phần R-C-T-F', '<p>Chất lượng câu trả lời phụ thuộc vào độ rõ của yêu cầu. Hãy áp dụng đều đặn:</p>' + table(['Chữ', 'Thành phần', 'Cần nêu gì', 'Ví dụ'], [
    ['<b>R</b>', 'Role – Vai trò', 'Chuyên môn AI cần đóng', '“Bạn là kế toán tổng hợp quản lý công nợ doanh nghiệp thương mại…”'],
    ['<b>C</b>', 'Context – Bối cảnh', 'Tình huống, người đọc, mục tiêu', '“…gửi thư nhắc thanh toán lần hai cho khách đã quá hạn 10 ngày nhưng vẫn cần giữ quan hệ lâu dài”'],
    ['<b>T</b>', 'Task – Nhiệm vụ', 'Động từ cụ thể: tóm tắt, lập bảng, so sánh, kiểm tra lỗi, viết công thức', '“Soạn email 120 từ, nêu số hóa đơn và hạn mới”'],
    ['<b>F</b>', 'Format – Định dạng', 'Độ dài, giọng văn, cấu trúc', '“Giọng lịch sự, có tiêu đề, kết bằng một câu chốt”']]))
b.card('So sánh câu lệnh yếu và câu lệnh chuẩn', ex('Nhân viên văn phòng', 'Viết giúp tôi báo cáo công việc tuần này.', 'Bạn là chuyên viên điều phối dự án. Dựa trên danh sách ghi chú đính kèm, hãy tổng hợp báo cáo tuần gửi quản lý trực tiếp gồm 3 mục: Việc đã hoàn thành, Việc đang vướng mắc cần hỗ trợ, Kế hoạch tuần tới. Trình bày dạng bảng ngắn gọn, không quá 1 trang.')
       + ex('Kế toán', 'Chỉ tôi công thức Excel tính tổng theo tháng.', 'Tôi có bảng Excel: cột A là Ngày chứng từ (dd/mm/yyyy), cột B là Mã phòng ban, cột C là Số tiền. Hãy viết công thức SUMIFS tính tổng số tiền của phòng ban ghi ở ô F2 trong tháng 10/2026, và giải thích ngắn gọn từng tham số.')
       + ex('Hành chính', 'Soạn thông báo nghỉ lễ cho công ty.', 'Bạn là nhân viên hành chính. Soạn thông báo lịch nghỉ lễ gửi toàn thể nhân viên: nghỉ từ [Ngày] đến hết [Ngày], đi làm lại [Ngày]. Nhắc các bộ phận bàn giao công việc, ngắt thiết bị điện trước khi rời văn phòng. Giọng trang trọng, có tiêu đề và nơi nhận chuẩn văn bản nội bộ.'))
b.card('Ba kỹ thuật nâng cao giúp giảm sai sót', ul(['<b>Cung cấp văn bản mẫu (few-shot):</b> đính kèm 1–2 email, tờ trình hoặc báo cáo cũ đã được duyệt; yêu cầu giữ nguyên cấu trúc, xưng hô, giọng văn.', '<b>Chia nhỏ tác vụ lớn:</b> yêu cầu lập dàn ý trước, duyệt dàn ý rồi mới viết từng mục.', '<b>Cho AI hỏi lại trước khi làm:</b> thêm câu chốt ở cuối.'])
       + prompt('CÂU CHỐT NÊN DÙNG', 'Nếu thiếu thông tin cần thiết để hoàn thành chính xác yêu cầu trên, hãy hỏi lại tôi tối đa 3 câu trước khi viết.'))
b.card('Thực hành: nâng ba câu lệnh yếu thành R-C-T-F', prac('', 'Viết lại từng câu lệnh yếu thành câu lệnh R-C-T-F dùng đúng dữ kiện bên dưới. Sau đó gửi cho Gemini và chấm kết quả bằng bảng tự kiểm.', [data('DỮ LIỆU MẪU – 3 câu yếu và dữ kiện', 'Câu 1 (văn phòng): “Viết email nhắc nộp báo cáo.”\n  Dữ kiện: gửi 4 trưởng nhóm; hạn 16:00 thứ Sáu 27/11/2026; gửi về baocao@congty-mau.vn; giọng lịch sự; 100–120 từ.\nCâu 2 (kế toán): “Giúp tôi cái công thức.”\n  Dữ kiện: cột A Ngày, cột B Mã phòng, cột C Số tiền; cần tổng số tiền phòng HC trong tháng 10/2026; kết quả đặt ở G2.\nCâu 3 (hành chính): “Làm quy trình đặt xe.”\n  Dữ kiện: nhân viên đặt xe công tác trước 1 ngày; trưởng phòng duyệt; bộ phận hành chính điều xe; cần bảng Bước – Người làm – Thời hạn.'), prompt('KHUNG ĐIỀN SẴN', 'Vai trò: [R]\nBối cảnh: [C]\nNhiệm vụ: [T]\nĐịnh dạng: [F]\nNếu thiếu thông tin, hỏi lại tôi tối đa 3 câu trước khi làm.')],
   ['Điền khung R-C-T-F cho từng câu, không nhìn đáp án.', 'Gửi cho Gemini, đọc kết quả.', 'Chấm: có đủ dữ kiện, không tự thêm thông tin, đúng định dạng yêu cầu không? Câu nào AI hỏi lại, câu hỏi đó có hợp lý không?'],
   ans(ul(['<b>Câu 1:</b> R = chuyên viên điều phối; C = cuối tháng cần tổng hợp, gửi 4 trưởng nhóm; T = soạn email nhắc nộp báo cáo; F = 100–120 từ, lịch sự, nêu hạn 16:00 thứ Sáu 27/11/2026 và địa chỉ baocao@congty-mau.vn. Kiểm tra: email phải có đủ hạn và địa chỉ, không thêm chế tài.', '<b>Câu 2:</b> R = kế toán; C = bảng cột A–C, cần tổng phòng HC tháng 10/2026; T = viết công thức SUMIFS, giải thích tham số; F = công thức đặt ở G2, kèm một dòng giải thích mỗi tham số. Kiểm tra: có điều kiện ngày từ 01/10 đến trước 01/11/2026.', '<b>Câu 3:</b> R = nhân viên hành chính; C = quy trình đặt xe công tác nội bộ; T = lập SOP; F = bảng Bước – Người làm – Thời hạn, đủ 3 bước (đặt trước 1 ngày, trưởng phòng duyệt, hành chính điều xe). Kiểm tra: không thêm bước hay biểu mẫu không có trong dữ kiện.'])), ) , ' tprac')
B['bai5'] = b.out()

# ---------------- Bài 6 ----------------
b = L('Bài 6 · Gemini cho nhân viên văn phòng: email, họp, báo cáo', 'Tóm tắt chuỗi email, soạn thư đúng cấp bậc, biên bản và bảng giao việc, sắp ưu tiên đầu việc tuần.',
      [('Học xong bài này', 'Xử lý email, họp và báo cáo nhanh hơn mà vẫn kiểm soát được nội dung'), ('Chuẩn bị', 'Chuỗi email mẫu và ghi chú họp ở phần thực hành'), ('Sản phẩm', 'Bản tóm tắt 3 mục, bảng giao việc, thư xin gia hạn')])
b.chap('Chương 3. Ứng dụng AI cho nhân viên văn phòng')
b.card('Xử lý email và giao tiếp chuyên nghiệp', '<p>Nhân viên văn phòng thường mất 1–2 giờ mỗi ngày cho email. AI rút ngắn qua ba việc:</p>' + ul(['Tóm tắt chuỗi email nhiều ngày để nắm điểm chốt.', 'Biến ý thô thành email chuẩn theo cấp bậc người nhận (cấp trên, đồng nghiệp, đối tác).', 'Rà ngữ pháp, giọng điệu trước khi gửi thư nhạy cảm: từ chối, nhắc tiến độ, xin gia hạn.'])
       + tip('Nếu email nằm trong Gmail và tài khoản có Gemini tích hợp, Anh/Chị có thể nhờ tóm tắt ngay trong hộp thư. Nhớ kiểm tra kết quả với thư gốc.'))
b.card('Chuẩn bị họp, ghi biên bản, quản lý đầu việc', '<p>Trước họp: đưa mục tiêu và danh sách người dự để AI lập chương trình nghị sự có phân bổ thời lượng. Sau họp: dán ghi chú nhanh (đã lọc thông tin mật) để AI tách thành ba phần:</p>' + ul(['<b>Quyết định</b> đã thống nhất.', '<b>Đầu việc</b> kèm người phụ trách và thời hạn.', '<b>Vấn đề bỏ ngỏ</b> cần theo dõi ở kỳ họp sau.']))
b.card('Tổng hợp báo cáo và dàn ý trình bày', ul(['Tải các báo cáo lẻ lên, yêu cầu hợp nhất theo một khung tiêu chí, chỉ ra điểm khác biệt hoặc mâu thuẫn giữa các nguồn.', 'Chuyển tài liệu Word dài thành dàn ý slide: mỗi slide một thông điệp chính và 3–4 ý phụ.']))
b.card('Bộ câu lệnh thực hành cho văn phòng', prompt('1. Tóm tắt chuỗi email dài', 'Hãy đọc chuỗi email dưới đây và tóm tắt thành 3 mục: (1) Vấn đề cốt lõi đang thảo luận, (2) Các nội dung đã được thống nhất kèm tên người xác nhận, (3) Việc tôi cần thực hiện tiếp theo và thời hạn.\n\n[dán chuỗi email]')
       + prompt('2. Từ chối hoặc xin gia hạn khéo léo', 'Tôi cần phản hồi yêu cầu [Mô tả yêu cầu] của [Đối tượng]. Hiện tôi chưa thể hoàn thành đúng hạn [Ngày cũ] do đang ưu tiên [Công việc ưu tiên]. Hãy soạn email lịch sự, thể hiện thiện chí hợp tác và đề xuất thời hạn mới là [Ngày mới].')
       + prompt('3. Biên bản họp và bảng giao việc', 'Dưới đây là ghi chú thô của cuộc họp [Tên cuộc họp]. Hãy viết lại thành biên bản gồm: Thông tin chung, Nội dung thảo luận chính, Kết luận, và bảng Giao việc 4 cột: STT, Hạng mục công việc, Người phụ trách, Thời hạn hoàn thành.\n\n[dán ghi chú]')
       + prompt('4. Sắp ưu tiên đầu việc tuần', 'Đây là danh sách việc tôi cần làm tuần này: [dán danh sách]. Hãy phân loại theo ma trận Eisenhower (Quan trọng/Khẩn cấp), gợi ý thứ tự từ Thứ Hai đến Thứ Sáu và chỉ ra các việc có thể gộp làm cùng một khung giờ.'))
b.card('Ví dụ: xin gia hạn mà vẫn giữ quan hệ', ex('Thư gửi đối tác', 'Tôi chưa làm xong, thứ Sáu tuần sau gửi nhé.', 'Kính gửi anh Nam, em xin lỗi vì báo cáo chưa kịp gửi đúng hạn 20/11 do em đang hoàn tất đợt kiểm kê cuối quý. Em xin đề xuất gửi trước 17:00 ngày 27/11 và sẽ gửi bản nháp số liệu chính ngay chiều 24/11 để anh xem trước. Mong anh thông cảm.', 'Cách chuẩn nêu lý do thật, đề xuất ngày cụ thể và có hành động bù.'))
b.card('Thực hành: tóm tắt chuỗi email và lập bảng giao việc', prac('', 'Anh/Chị là Mai (Kinh doanh). Dán chuỗi email vào Gemini bằng prompt số 1, sau đó lập thư và bảng giao việc. Tự tóm tắt trước rồi mới so sánh.', [data('DỮ LIỆU MẪU – chuỗi email (đã ẩn danh)', '[3/11] Mai (Kinh doanh): Nhờ Kho chuẩn bị 200 thùng cho đơn khách Sao Mai, giao ngày 14/11.\n[4/11] Tuấn (Kho): Kho hiện có 150 thùng, 50 thùng nhập về ngày 10/11.\n[4/11] Mai: Vậy giao làm 2 đợt được không? Đợt 1 ngày 12/11, đợt 2 ngày 14/11.\n[5/11] Hà (Kế toán): Cần chốt đơn giá trước 8/11 để xuất hóa đơn đợt 1. Chưa thấy báo giá chốt.\n[6/11] Mai: Khách đồng ý giao 2 đợt. Đơn giá giữ 85.000 đồng/thùng như báo giá cũ.\n[6/11] Tuấn: Kho xác nhận 2 đợt: 150 thùng ngày 12/11 và 50 thùng ngày 14/11.\n[7/11] Hà: Ghi nhận. Tôi xuất hóa đơn đợt 1 trước 12/11. Nhờ Mai gửi biên bản giao nhận đợt 1 sau khi giao.')],
   ['Tự viết tóm tắt 3 mục: vấn đề cốt lõi, đã thống nhất (ai xác nhận), việc của Mai.', 'Gửi prompt số 1 cho Gemini, so với bản của Anh/Chị.', 'Tính giá trị từng đợt và cả đơn; kiểm tra AI có tính đúng không.'],
   ans(ul(['<b>Vấn đề cốt lõi:</b> giao 200 thùng cho khách Sao Mai đúng 14/11 trong khi kho chỉ có 150 thùng.', '<b>Đã thống nhất:</b> giao 2 đợt, 150 thùng ngày 12/11 và 50 thùng ngày 14/11 (khách đồng ý do Mai báo, Kho xác nhận: Tuấn); đơn giá 85.000 đồng/thùng (Mai nêu, Hà chỉ “ghi nhận” nên nên chốt bằng văn bản); Hà xuất hóa đơn đợt 1 trước 12/11.', '<b>Việc của Mai:</b> gửi biên bản giao nhận đợt 1 cho Hà sau khi giao ngày 12/11.', '<b>Số tiền:</b> cả đơn 200 × 85.000 = 17.000.000 đồng; đợt 1 = 12.750.000 đồng; đợt 2 = 4.250.000 đồng.'])), ) , ' tprac')
B['bai6'] = b.out()

# ---------------- Bài 7 ----------------
b = L('Bài 7 · Gemini cho kế toán: bảng tính, đối chiếu, thuyết minh', 'Viết và sửa công thức Excel/Google Sheets, làm sạch dữ liệu, rà bất thường, soạn thuyết minh và email công nợ.',
      [('Học xong bài này', 'Dùng AI viết công thức và tìm bất thường mà vẫn kiểm tra được kết quả trên chứng từ gốc'), ('Chuẩn bị', 'Google Sheets hoặc Excel; hai bộ dữ liệu mẫu ở phần thực hành'), ('Sản phẩm', 'Công thức SUMIFS đúng, bảng tỷ lệ biến động, 3 mẫu email nhắc nợ')])
b.parts.append('<div class="card warn"><div class="lbl">Lưu ý nghề nghiệp bắt buộc</div><p>AI chỉ hỗ trợ thao tác và tổng hợp, không thay thế phần mềm kế toán hay phán đoán của kế toán viên. Mọi kết quả tính toán, định khoản và căn cứ pháp lý do AI gợi ý phải được kiểm tra lại trên chứng từ gốc và văn bản pháp luật hiện hành.</p></div>')
b.chap('Chương 4. Ứng dụng AI thực chiến cho bộ phận kế toán')
b.card('Tăng tốc bảng tính Excel và Google Sheets', ul(['<b>Viết và sửa công thức:</b> mô tả cấu trúc cột và kết quả mong muốn để AI viết XLOOKUP, SUMIFS, COUNTIFS, INDEX-MATCH, IF lồng nhau hoặc QUERY trên Google Sheets. Công thức báo lỗi (#N/A, #VALUE!, #REF!) thì dán công thức cùng mô tả dữ liệu để AI chỉ nguyên nhân.', '<b>Làm sạch và chuẩn hóa:</b> tách họ tên, chuẩn hóa ngày tháng, xóa khoảng trắng thừa, lọc mã số thuế sai độ dài, gộp nhiều sheet thành một bảng tổng hợp (công thức, VBA hoặc Apps Script).'])
       + tip('Làm trên Google Sheets thì Gemini phù hợp vì cùng hệ Google. Luôn thử công thức trên 3–5 dòng có đáp án biết trước rồi mới áp dụng cả bảng.'))
b.card('Đối chiếu, rà bất thường và thuyết minh số liệu', '<p>Trước khi khóa sổ, dùng AI (với dữ liệu đã ẩn danh) để:</p>' + ul(['Tìm dòng chứng từ trùng số hóa đơn.', 'Phát hiện khoản chi tăng đột biến so với trung bình các tháng trước.', 'So tỷ trọng chi phí giữa các phòng ban.', 'Sau khi có số chính xác từ phần mềm kế toán, nhờ AI soạn phần nhận xét, thuyết minh biến động gửi ban giám đốc.']))
b.card('Tra cứu nghiệp vụ và giao tiếp công nợ', ul(['Có văn bản mới về thuế, hóa đơn điện tử, chế độ kế toán: tải PDF toàn văn lên AI, yêu cầu bảng so sánh điểm thay đổi với quy định cũ và việc kế toán cần lưu ý. <b>Luôn đối chiếu văn bản gốc.</b>', 'Soạn mẫu email đối chiếu công nợ định kỳ, nhắc thanh toán theo cấp quá hạn, thư giải trình với kiểm toán hoặc đối tác.']))
b.card('Bộ câu lệnh thực hành cho kế toán', prompt('1. Công thức đối chiếu hai bảng', 'Tôi có 2 sheet: “SoPhu” (cột B là Số tiền, cột C là Nội dung chuyển khoản) và “CongNo” (cột A là Mã khách hàng, cột D là Số tiền phải thu). Hãy viết công thức kiểm tra khoản tiền ở “SoPhu” có khớp “CongNo” không, trả về “Đã khớp” hoặc “Cần kiểm tra”.')
       + prompt('2. Rà bất thường bảng chi phí', 'Dưới đây là bảng chi phí vận hành 6 tháng (đã ẩn danh). Tính tỷ lệ tăng giảm của từng khoản mục ở tháng gần nhất so với trung bình 5 tháng trước, chỉ ra 3 khoản biến động mạnh nhất và gợi ý các câu hỏi cần kiểm tra lại chứng từ gốc.\n\n[dán bảng]')
       + prompt('3. Tóm tắt thông tư, nghị định mới', 'Tôi đính kèm toàn văn [Tên văn bản]. Đóng vai kế toán trưởng doanh nghiệp [Loại hình], tóm tắt các quy định ảnh hưởng trực tiếp đến xuất hóa đơn và kê khai thuế, trình bày bảng: Điều khoản, Nội dung chính, Thời điểm áp dụng, Việc kế toán cần làm.')
       + prompt('4. Email đối chiếu và nhắc công nợ', 'Viết 3 mẫu email nhắc thanh toán công nợ khách B2B: Mẫu 1 nhắc nhẹ trước hạn 3 ngày; Mẫu 2 quá hạn 7 ngày; Mẫu 3 quá hạn 30 ngày, cần xác nhận lịch thanh toán cụ thể. Giọng chuyên nghiệp, tôn trọng, chừa chỗ trống cho số hóa đơn và số tiền.'))
b.card('Thực hành: SUMIFS theo tháng và rà bất thường', prac('', 'Phần A: dán bảng chứng từ vào Google Sheets (ô A1), nhờ Gemini viết công thức tính tổng phòng HC trong tháng 10/2026. Phần B: tính tỷ lệ biến động của bảng chi phí 6 tháng. Tự tính tay trước.', [data('PHẦN A – bảng chứng từ (cột A–C)', 'Ngày chứng từ\tMã phòng\tSố tiền\n05/10/2026\tHC\t1500000\n12/10/2026\tKT\t2200000\n18/10/2026\tHC\t800000\n25/10/2026\tHC\t1200000\n03/11/2026\tHC\t900000\n07/10/2026\tKD\t3000000\n20/10/2026\tKT\t1100000\n28/10/2026\tKD\t2500000'),
     data('PHẦN B – chi phí vận hành 6 tháng (triệu đồng)', 'Khoản mục\tT5\tT6\tT7\tT8\tT9\tT10\nĐiện\t10\t10.5\t11\t10.8\t11.2\t12\nVăn phòng phẩm\t2\t2.2\t1.8\t2\t2\t3.5\nVận chuyển\t8\t8.4\t8.2\t8.6\t8.8\t9'),
     prompt('PROMPT PHẦN A', 'Bảng ở A1:C9: cột A là Ngày chứng từ (dd/mm/yyyy), cột B là Mã phòng, cột C là Số tiền. Viết công thức SUMIFS tính tổng số tiền của phòng ghi ở F2 trong tháng 10/2026, giải thích từng tham số và nêu lưu ý nếu cột ngày bị lưu dạng văn bản.')],
   ['Tự tính tổng phòng HC tháng 10 và hai phòng còn lại.', 'Áp dụng công thức của Gemini, so với kết quả tay. Chú ý dòng 03/11.', 'Phần B: dùng prompt rà bất thường ở trên, kiểm tra AI tính đúng trung bình 5 tháng không.'],
   ans(ul(['<b>Phần A (tháng 10/2026):</b> HC = 1.500.000 + 800.000 + 1.200.000 = <b>3.500.000</b> (dòng 03/11 không tính); KT = 3.300.000; KD = 5.500.000; tổng 12.300.000.', 'Công thức mẫu: <code>=SUMIFS(C2:C9,B2:B9,F2,A2:A9,"&gt;="&amp;DATE(2026,10,1),A2:A9,"&lt;"&amp;DATE(2026,11,1))</code> với F2 = HC.', '<b>Phần B:</b> Điện: trung bình 5 tháng 10,7 → T10 12,0 tăng 12,15%. Văn phòng phẩm: trung bình 2,0 → 3,5 tăng 75%. Vận chuyển: trung bình 8,4 → 9,0 tăng 7,14%.', 'Mạnh nhất: văn phòng phẩm (+75%), điện (+12,15%), vận chuyển (+7,14%). Câu hỏi kiểm tra: văn phòng phẩm tháng 10 có đợt mua lớn hoặc nhập nhầm khoản mục không? Nhớ rằng tăng 75% ở khoản nhỏ vẫn chỉ là 1,5 triệu đồng.'])), ) , ' tprac')
B['bai7'] = b.out()

# ---------------- Bài 8 ----------------
b = L('Bài 8 · Gemini cho hành chính: văn bản, SOP, báo giá, sự kiện', 'Soạn văn bản đúng thể thức, chuẩn hóa quy trình thành SOP và FAQ, so sánh báo giá khách quan, lập kế hoạch hậu cần.',
      [('Học xong bài này', 'Soạn nháp văn bản, SOP; so sánh báo giá và phát hiện chi phí ẩn; lập checklist sự kiện'), ('Chuẩn bị', 'Mẫu thể thức văn bản của cơ quan (nếu có); bảng báo giá mẫu ở phần thực hành'), ('Sản phẩm', 'Một SOP ngắn, bảng so sánh 3 báo giá, checklist sự kiện')])
b.chap('Chương 5. Ứng dụng AI thực chiến cho bộ phận hành chính')
b.card('Soạn thảo văn bản hành chính đúng thể thức', '<p>Hành chính gắn với nhiều loại văn bản: thông báo nội bộ, công văn, tờ trình mua sắm, quyết định điều chuyển tài sản, biên bản bàn giao, nội quy. AI rút ngắn thời gian soạn nháp và giữ cách trình bày thống nhất. Anh/Chị cần cung cấp:</p>' + ul(['Căn cứ và nội dung chính.', 'Thời gian hiệu lực, bộ phận liên quan.', 'Mẫu thể thức của công ty.']))
b.card('Xây dựng SOP và biểu mẫu', '<p>Hành chính hay phải trả lời lặp lại: đặt xe công tác, cấp văn phòng phẩm, thanh toán tiếp khách, báo hỏng thiết bị… Chuẩn hóa thành SOP gồm:</p>' + ul(['Mục đích và phạm vi áp dụng.', 'Các bước: ai làm, làm gì, thời hạn xử lý.', 'Bộ câu hỏi thường gặp (FAQ) phát cho nhân sự mới ngày đầu đi làm.']))
b.card('So sánh báo giá, quản lý nhà cung cấp, tổ chức sự kiện', ul(['<b>So sánh báo giá khách quan:</b> đưa báo giá 3–4 nhà cung cấp, yêu cầu bảng chung theo đơn giá, VAT, điều kiện giao hàng, bảo hành, điều khoản thanh toán; chỉ ra chi phí ẩn và hạng mục không đồng nhất.', '<b>Hậu cần và sự kiện:</b> yêu cầu kịch bản, bảng phân công, dự trù ngân sách và checklist theo mốc (trước 2 tuần, 1 tuần, 1 ngày, trong ngày).']))
b.card('Bộ câu lệnh thực hành cho hành chính', prompt('1. Tờ trình mua sắm, sửa chữa', 'Bạn là chuyên viên hành chính. Soạn tờ trình gửi Ban Giám đốc đề xuất [Nội dung, ví dụ: thay mới máy in tầng 3]. Nêu: Hiện trạng thiết bị, Lý do cần thực hiện, Bảng so sánh 3 báo giá (chừa ô điền số liệu), Đề xuất nhà cung cấp tối ưu, Thời gian dự kiến hoàn thành.')
       + prompt('2. SOP', 'Xây dựng quy trình vận hành chuẩn cho việc [Tên quy trình, ví dụ: Đặt vé máy bay và thanh toán công tác phí]. Gồm: Mục đích, Đối tượng áp dụng, Các bước theo bảng (Bước, Người thực hiện, Nội dung chi tiết, Biểu mẫu đi kèm, Thời gian xử lý tối đa), Lưu ý các trường hợp ngoại lệ.')
       + prompt('3. Phân tích và so sánh báo giá', 'Tôi đính kèm 3 báo giá dịch vụ [Tên dịch vụ] từ nhà cung cấp A, B, C. Lập bảng đối chiếu theo từng hạng mục, tính tổng chi phí đã gồm VAT, chỉ ra hạng mục bên này có mà bên kia không ghi rõ để tôi hỏi lại trước khi chốt.')
       + prompt('4. Checklist tổ chức sự kiện', 'Tôi cần tổ chức [Tên sự kiện, ví dụ: tiệc tất niên] cho [Số lượng] nhân viên, ngân sách dự kiến [Ngân sách]. Lập kế hoạch gồm: bảng phân bổ ngân sách dự kiến và checklist công việc từ trước 14 ngày đến sau khi kết thúc sự kiện.'))
b.card('Ví dụ: tờ trình có chỗ để người quyết định', ex('Tờ trình thay máy in', 'Soạn tờ trình mua máy in mới.', 'Bạn là chuyên viên hành chính. Soạn tờ trình gửi Ban Giám đốc đề xuất thay máy in tầng 3. Hiện trạng: máy dùng 6 năm, hỏng 4 lần trong 6 tháng (số liệu do tôi cung cấp bên dưới). Bảng so sánh 3 báo giá chừa ô trống. Phần đề xuất chỉ nêu tiêu chí chọn, KHÔNG tự chọn nhà cung cấp. Thiếu thông tin thì ghi [CẦN BỔ SUNG].', 'Cách chuẩn giữ quyền quyết định cho người ký và cấm AI tự điền thông tin.'))
b.card('Thực hành: so sánh ba báo giá dịch vụ vệ sinh', prac('', 'Phạm vi so sánh: 1 quý (3 tháng). Giả định của bài tập: thuế VAT 10% ở những nơi ghi “chưa gồm” (thuế suất thật phải kiểm tra theo quy định hiện hành). Tự tính tổng từng bên trước.', [data('DỮ LIỆU MẪU – ba báo giá', 'Hạng mục\tNCC A\tNCC B\tNCC C\nVệ sinh hằng ngày (đ/tháng)\t6000000\t5500000\t6200000\nVệ sinh kính (đ/quý)\t1500000\t(không ghi)\t1800000\nVật tư tiêu hao\tđã gồm\t800000 đ/tháng\tđã gồm\nVAT\tchưa gồm\tđã gồm\tchưa gồm'), prompt('PROMPT GỢI Ý', 'Tôi đính kèm 3 báo giá dịch vụ vệ sinh văn phòng cho 1 quý (3 tháng) từ A, B, C. Lập bảng đối chiếu theo từng hạng mục, tính tổng chi phí đã gồm VAT 10% ở những nơi ghi “chưa gồm”, chỉ ra hạng mục thiếu hoặc chưa đồng nhất để tôi hỏi lại. Không kết luận chọn nhà cung cấp nào. Ghi công thức tính từng tổng.\n\n[dán bảng]')],
   ['Tự tính tổng cho A, B, C.', 'Gửi prompt cho Gemini và kiểm tra từng phép tính.', 'Lập danh sách câu hỏi cần gửi từng nhà cung cấp trước khi chốt.'],
   ans(ul(['<b>A:</b> 3 × 6.000.000 + 1.500.000 = 19.500.000; cộng VAT 10% = <b>21.450.000</b>.', '<b>B:</b> 3 × 5.500.000 + 3 × 800.000 = 18.900.000 (đã gồm VAT) <b>nhưng thiếu hạng mục vệ sinh kính</b>, nên chưa so sánh công bằng được.', '<b>C:</b> 3 × 6.200.000 + 1.800.000 = 20.400.000; cộng VAT 10% = <b>22.440.000</b>.', 'Không được kết luận B rẻ nhất: cần hỏi B giá vệ sinh kính. Hỏi A và C: “đã gồm vật tư” gồm những gì. Hỏi cả ba: thời hạn hợp đồng, phạt khi vi phạm, nhân sự thay thế.'])), ) , ' tprac')
B['bai8'] = b.out()


# ---------------- Bài 9 (mới): hệ sinh thái Google ----------------
b = L('Bài 9 · Gemini trong hệ sinh thái Google và NotebookLM', 'Dùng Gemini ngay trong Gmail, Docs, Sheets, Drive, Meet; kết nối dữ liệu bằng lệnh @ và xây kho tra cứu quy chế bằng NotebookLM.',
      [('Học xong bài này', 'Biết Gemini hỗ trợ gì trong từng ứng dụng Google, dùng lệnh @ để gom dữ liệu, dựng kho tra cứu có trích dẫn nguồn'), ('Chuẩn bị', 'Tài khoản Google Workspace (hoặc Google cá nhân để tập); hai bộ dữ liệu mẫu ở phần thực hành'), ('Sản phẩm', 'Một công thức QUERY chạy đúng; một bộ câu hỏi tra cứu quy chế có đối chiếu điều khoản gốc')])
b.parts.append(WARN)
b.chap('Chương 6. Ứng dụng AI trong hệ sinh thái Google')
b.card('Làm việc với AI ở bảng điều khiển bên phải (Side Panel)', '<p>Với doanh nghiệp dùng Google Workspace, lợi thế lớn nhất là không phải sao chép dữ liệu qua lại giữa nhiều cửa sổ. Gemini nằm ở bảng điều khiển bên phải trong từng ứng dụng, xử lý theo đúng tệp đang mở:</p>' + table(['Ứng dụng', 'Tính năng AI trọng tâm', 'Ứng dụng cho văn phòng – kế toán – hành chính'], [
    ['<b>Gmail</b>', 'Tóm tắt chuỗi thư dài, gợi ý câu trả lời theo ngữ cảnh, truy tìm thông tin cũ', 'Nắm điểm chốt, đối chiếu công nợ, phản hồi nhà cung cấp, tổng hợp yêu cầu từ các phòng'],
    ['<b>Google Docs</b>', 'Soạn nháp từ gạch đầu dòng, chỉnh giọng văn từng đoạn, tham chiếu tệp từ Drive', 'Hoàn thiện tờ trình, thông báo nội bộ, SOP, biên bản họp đúng văn phong doanh nghiệp'],
    ['<b>Google Sheets</b>', 'Tạo bảng theo dõi, viết hàm phức tạp (QUERY, ARRAYFORMULA, XLOOKUP), phân loại dữ liệu', 'Theo dõi ngân sách văn phòng, đối chiếu bảng kê chi phí, tổng hợp chấm công, phân loại phản hồi nhân sự'],
    ['<b>Google Drive</b>', 'Tóm tắt nhanh PDF hoặc tài liệu lớn, so sánh nhiều tệp trong cùng thư mục', 'Đối chiếu 3 báo giá trong một thư mục mua sắm, tổng hợp báo cáo tuần từ nhiều bộ phận'],
    ['<b>Google Meet &amp; Calendar</b>', 'Ghi chú cuộc họp tự động (Take notes for me), trích đầu việc, rà soát lịch', 'Tự tạo biên bản kèm danh sách người phụ trách, gửi về Docs hoặc Gmail khi kết thúc họp']])
       + tip('Tính năng nào có sẵn phụ thuộc gói Workspace và cài đặt của quản trị viên. Nếu chưa thấy, hỏi bộ phận IT trước khi cho rằng Gemini “không làm được”.'))
b.card('Kết nối dữ liệu liên ứng dụng bằng lệnh @', '<p>Trong cửa sổ làm việc chính của Gemini, gõ ký tự <b>@</b> để kết nối trực tiếp với kho dữ liệu Google của cá nhân hoặc doanh nghiệp, không cần tự tìm từng tệp:</p>' + ul(['<b>@Gmail:</b> tìm nhanh email liên quan đến một đối tác, hóa đơn hoặc dự án trong khoảng thời gian xác định, tổng hợp thành bảng theo dõi.', '<b>@Google Drive:</b> đọc và so sánh nội dung nhiều tệp tài liệu, báo giá, biểu mẫu trên Drive.', '<b>@Google Docs:</b> trích dữ liệu từ một tài liệu quy định hoặc báo cáo cũ làm căn cứ soạn văn bản mới.'])
       + '<div class="card warn"><div class="lbl">Dùng lệnh @ an toàn</div>' + ul(['Lệnh @ đọc dữ liệu thật trong tài khoản, nên chỉ dùng với tài khoản công việc được phép, không dùng khi hộp thư có thông tin nhạy cảm không liên quan.', 'Luôn nêu phạm vi: khoảng thời gian, tên đối tác, thư mục cụ thể.', 'Kiểm tra kết quả với thư hoặc tệp gốc trước khi gửi đi, như quy tắc ở Bài 10.']) + '</div>')
b.card('Kho tra cứu quy chế nội bộ với NotebookLM', '<p>Khác khung chat thông thường, NotebookLM (công cụ ghi chú AI của Google) chỉ trả lời dựa trên bộ tài liệu Anh/Chị tải lên và kèm số trích dẫn chỉ đoạn gốc. Rất hợp với hành chính và kế toán:</p>' + ul(['<b>Cổng giải đáp nội quy và SOP:</b> tải sổ tay nhân viên, quy chế công tác phí, quy trình đặt phòng họp, chính sách phúc lợi. Khi nhân sự hỏi, tra ra câu trả lời kèm điều khoản gốc.', '<b>Kho tra cứu văn bản thuế và kế toán:</b> sổ tay riêng chứa thông tư, nghị định hiện hành và quy chế tài chính nội bộ, để đối chiếu điều kiện khấu trừ hoặc chứng từ hợp lệ, hạn chế AI suy diễn ngoài nguồn.'])
       + tip('Có trích dẫn không có nghĩa là luôn đúng. Hãy bấm vào số trích dẫn, đọc đoạn gốc, và đừng tải tài liệu mật khi chưa được phép.'))
b.card('Bộ câu lệnh thực hành cho hệ sinh thái Google', prompt('1. Tổng hợp email đối tác (@Gmail)', '@Gmail Hãy tìm toàn bộ email trao đổi với [Tên nhà cung cấp / Đối tác] trong 30 ngày qua liên quan đến [Tên hạng mục/Hợp đồng]. Tổng hợp thành bảng gồm: Ngày gửi, Nội dung cam kết, Các điểm chưa thống nhất và Việc tôi cần phản hồi.')
       + prompt('2. Đối chiếu nhiều tệp (@Google Drive)', '@Google Drive Hãy đọc các tệp trong thư mục [Tên thư mục báo giá/báo cáo] và lập bảng so sánh các điểm giống và khác nhau về đơn giá, thời gian giao hàng và điều khoản thanh toán.')
       + prompt('3. Tự động hóa bảng tính (Google Sheets)', 'Trong bảng tính này, cột A là Ngày chi, cột B là Phòng ban, cột C là Hạng mục, cột D là Số tiền. Hãy viết hàm QUERY tổng hợp tổng chi phí theo từng Phòng ban trong tháng hiện tại và sắp xếp từ cao xuống thấp.')
       + prompt('4. Tra cứu quy chế (NotebookLM)', 'Dựa hoàn toàn vào các tài liệu quy chế đã tải lên, hãy liệt kê đầy đủ hạn mức thanh toán công tác phí (di chuyển, lưu trú, phụ cấp) áp dụng cho cấp [Chức danh] và các chứng từ bắt buộc phải nộp kèm khi hoàn ứng.'))
b.card('Ví dụ: tìm email đối tác có phạm vi rõ ràng', ex('Truy tìm email trong Gmail', 'Tìm email về nhà cung cấp.', '@Gmail Tìm email trao đổi với Công ty Sao Mai trong 30 ngày qua về hợp đồng HD-045. Lập bảng: Ngày gửi, Cam kết, Điểm chưa thống nhất, Việc tôi cần phản hồi. Chỉ dùng nội dung có trong email, thiếu thì ghi “không có”.', 'Cách chuẩn nêu rõ đối tác, hợp đồng, khoảng thời gian, cột của bảng và cấm AI tự điền.'))
b.card('Thực hành: quy chế công tác phí và hàm QUERY', prac('', 'Phần A mô phỏng NotebookLM: dán “quy chế” bên dưới vào Gemini (hoặc nguồn NotebookLM), chỉ cho phép trả lời dựa trên văn bản. Phần B: dán bảng chi vào Google Sheets (ô A1) và nhờ Gemini viết hàm QUERY. Tự tính trước.', [data('PHẦN A – quy chế công tác phí (giả lập)', 'Điều 1. Phạm vi: áp dụng cho nhân viên đi công tác trong nước.\nĐiều 2. Di chuyển: đi máy bay hạng phổ thông khi quãng đường trên 500 km; từ 500 km trở xuống đi xe khách hoặc tàu.\nĐiều 3. Lưu trú: cấp trưởng phòng tối đa 1.200.000 đồng/đêm; nhân viên tối đa 800.000 đồng/đêm.\nĐiều 4. Phụ cấp ăn: 200.000 đồng/ngày cho mọi cấp.\nĐiều 5. Hoàn ứng: nộp trong 5 ngày làm việc sau chuyến đi, kèm vé, hóa đơn lưu trú và giấy đề nghị công tác đã duyệt.'),
     data('PHẦN B – bảng chi (cột A–D, dòng 1 là tiêu đề)', 'Ngày chi\tPhòng ban\tHạng mục\tSố tiền\n02/11/2026\tKD\tVé tàu\t1200000\n05/11/2026\tHC\tVăn phòng phẩm\t600000\n09/11/2026\tKD\tTiếp khách\t2800000\n12/11/2026\tKT\tPhần mềm\t1500000\n15/11/2026\tHC\tVệ sinh\t2000000\n28/10/2026\tKD\tTiếp khách\t900000'),
     prompt('PROMPT PHẦN A', 'Dựa hoàn toàn vào văn bản quy chế dưới đây, trả lời: một nhân viên (không phải trưởng phòng) đi công tác Hà Nội 3 ngày 2 đêm, quãng đường 450 km, được thanh toán tối đa bao nhiêu cho lưu trú và phụ cấp ăn, đi bằng phương tiện nào, cần nộp chứng từ gì? Mỗi ý ghi rõ Điều nào. Câu nào văn bản không nói đến thì trả lời “quy chế không quy định”. Thêm câu hỏi: mức thưởng cho chuyến công tác là bao nhiêu?\n\n[dán quy chế]'),
     prompt('PROMPT PHẦN B', 'Trong bảng tính này, cột A là Ngày chi (dạng ngày), cột B là Phòng ban, cột C là Hạng mục, cột D là Số tiền, dòng 1 là tiêu đề, dữ liệu ở A1:D7. Viết hàm QUERY tổng chi phí theo từng phòng ban trong tháng 11/2026, sắp xếp từ cao xuống thấp, và giải thích từng phần của hàm.')],
   ['Phần A: tự tìm đáp án trong văn bản trước, rồi so với câu trả lời của Gemini. Chú ý câu về mức thưởng.', 'Phần B: dán bảng, áp dụng hàm Gemini đưa ra; nếu báo lỗi, kiểm tra cột A đã là dạng ngày chưa.', 'So kết quả với đáp án. Dòng 28/10 phải bị loại.'],
   ans(ul(['<b>Phần A:</b> lưu trú tối đa 2 đêm × 800.000 = 1.600.000 đồng (Điều 3); phụ cấp ăn 3 ngày × 200.000 = 600.000 đồng (Điều 4); tổng tối đa 2.200.000 đồng chưa gồm tiền di chuyển. Quãng đường 450 km không vượt 500 km nên đi xe khách hoặc tàu (Điều 2). Chứng từ hoàn ứng: vé, hóa đơn lưu trú, giấy đề nghị công tác đã duyệt, nộp trong 5 ngày làm việc (Điều 5). Mức thưởng: <b>quy chế không quy định</b>. Nếu AI tự nêu một mức thưởng, đó là bịa.', '<b>Phần B:</b> tháng 11/2026: KD = 1.200.000 + 2.800.000 = <b>4.000.000</b>; HC = 600.000 + 2.000.000 = <b>2.600.000</b>; KT = <b>1.500.000</b>. Dòng 28/10 (900.000) không tính.', 'Hàm mẫu: <code>=QUERY(A1:D7,"select B, sum(D) where A &gt;= date \'2026-11-01\' and A &lt; date \'2026-12-01\' group by B order by sum(D) desc label sum(D) \'Tổng\'",1)</code>.'])), ) , ' tprac')
B['bai9'] = b.out()

# ---------------- Bài 10 (bảo mật) ----------------
b = L('Bài 10 · Bảo mật dữ liệu và kiểm duyệt đầu ra', 'Quy tắc 3 không, kỹ thuật ẩn danh, và quy trình 3 bước kiểm duyệt trước khi gửi đi.',
      [('Học xong bài này', 'Ẩn danh được dữ liệu trước khi đưa vào AI; kiểm duyệt đầu ra theo 3 bước'), ('Chuẩn bị', 'Hai dữ liệu mẫu ở phần thực hành'), ('Sản phẩm', 'Bản dữ liệu đã ẩn danh; danh sách lỗi tìm được trong bản nháp của AI')])
b.chap('Chương 7. Bảo mật dữ liệu và kiểm duyệt đầu ra')
b.card('Nguyên tắc vàng về bảo mật thông tin doanh nghiệp', '<p>Khối văn phòng, kế toán, hành chính tiếp xúc nhiều dữ liệu nhạy cảm nhất. Dùng AI thiếu kiểm soát có thể làm lộ thông tin tài chính, dữ liệu cá nhân nhân sự hoặc bí mật kinh doanh.</p>'
       + '<div class="card warn"><div class="lbl">Quy tắc 3 không</div>' + ul(['<b>Không</b> đưa dữ liệu định danh cá nhân lên tài khoản AI miễn phí: số CCCD, số tài khoản ngân hàng, bảng lương chi tiết, hồ sơ sức khỏe, thông tin liên hệ cá nhân của nhân viên và khách hàng.', '<b>Không</b> tải bí mật kinh doanh và chứng từ gốc chưa che mờ: hợp đồng độc quyền, báo cáo tài chính chưa công bố, mật khẩu hệ thống, mã truy cập phần mềm kế toán.', '<b>Không</b> dùng tài khoản cá nhân khi công ty đã cấp tài khoản doanh nghiệp. Ưu tiên gói doanh nghiệp có cam kết không dùng dữ liệu để huấn luyện mô hình, hoặc bật chế độ trò chuyện tạm thời nếu công cụ có.']) + '</div>')
b.card('Kỹ thuật ẩn danh trước khi xử lý', ul(['Đổi tên khách hàng thành “Khách hàng A, B”, tên nhân viên thành “NV01, NV02”.', 'Chỉ gửi phần dữ liệu cần thiết, không gửi cả tệp gốc.', 'Cột không cần cho việc đang làm (CCCD, số tài khoản) thì xóa hẳn, không chỉ che.', 'Lưu bảng đối chiếu tên thật – mã ẩn danh ở nơi riêng, không đưa vào AI.']))
b.card('Quy trình 3 bước kiểm duyệt đầu ra', '<p>Người ký tên hoặc nhấn nút gửi là người chịu trách nhiệm cuối cùng. Hãy dành 2–3 phút:</p>' + steps(['<b>Kiểm tra dữ kiện và con số:</b> đối chiếu số tiền, ngày tháng, tên riêng, mã hợp đồng, kết quả công thức với chứng từ gốc.', '<b>Kiểm tra nghiệp vụ và pháp lý:</b> đúng quy chế nội bộ, thẩm quyền phê duyệt, quy định hiện hành.', '<b>Chỉnh giọng văn tự nhiên:</b> bỏ câu mở đầu sáo rỗng, cụm từ máy móc để đúng phong thái của Anh/Chị.']))
